function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#5a3a10', Y='#e0a820', YLt='#f4d060', YDk='#b07818';
  // tab
  px(4,6,12,6,O); px(5,7,10,5,YLt);
  // body
  px(4,10,24,18,O); px(5,11,22,16,Y);
  px(5,11,22,2,YLt); px(5,25,22,2,YDk);

}
